function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30, 0, 2*Math.PI);
  ctx.stroke();

  // worst case scenario
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('WORST CASE', W/2, H/2 - 45);

  // catastrophizing effect
  ctx.beginPath();
  ctx.lineWidth = 2;
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2, H/2 - 30 + 50*Math.sin(t));
  ctx.stroke();

  // escalating worry
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2, H/2 - 30 + i*10, 2 + i, 0, 2*Math.PI);
    ctx.stroke();
  }

  ctx.restore();
}
